const telegramId = $('Parse Input').item.json.telegramId;

let query;
if (telegramId) {
  query = `
SELECT
  d.id AS draft_id,
  d.topic_id,
  d.script_hook,
  d.script_body,
  d.script_cta,
  d.full_script,
  d.status,
  d.revision_count,
  d.word_count
FROM public.youtube_drafts d
JOIN public.youtube_topics t ON t.id = d.topic_id
JOIN public.telegram_users u ON u.id = t.telegram_user_id
WHERE u.telegram_id = ${telegramId}
ORDER BY d.created_at DESC
LIMIT 1;
`;
} else {
  // Chat UI fallback — ultimul draft din DB
  query = `
SELECT
  d.id AS draft_id,
  d.topic_id,
  d.script_hook,
  d.script_body,
  d.script_cta,
  d.full_script,
  d.status,
  d.revision_count,
  d.word_count
FROM public.youtube_drafts d
ORDER BY d.created_at DESC
LIMIT 1;
`;
}

return [{ json: {
  query: query.trim(),
  chatId: $('Parse Input').item.json.chatId
} }];

const fmt = $('Format Final Output').item.json;
const seo = $('Parse SEO Response').item.json.seo || {};
const voiceOutput = $input.first().json.output || $input.first().json.text || fmt.full_script_raw || '';
const tagsArr = Array.isArray(seo.tags) ? seo.tags : [];
const sections = $('Parse Script Response').item.json.sections || [];
const timestamps = sections.map(s => s.timestamp + ' ' + s.title).join('\n');
const descWithTs = (seo.description || '') + (timestamps ? '\n\n' + timestamps : '');
return [{ json: {
  title: seo.title_1 || fmt.message?.split('\n')[0] || 'YouTube Video',
  description: descWithTs,
  tags: tagsArr.join(','),
  voiceover_script: voiceOutput,
  thumbnail_prompt: $('Parse Thumbnail Response').item.json.thumb?.prompt_text || '',
  chatId: fmt.chatId,
  message: fmt.message,
  draftId: fmt.draftId,
  videoFile: 'data',
  generated_at: new Date().toISOString()
}}];

// Detecteaza sursa: Telegram Trigger vs n8n Chat UI
const isTelegram = !!$json.message;
const msg = $json.message || {};

// Text input
const text = isTelegram
  ? (msg.text || '').trim()
  : ($json.chatInput || $json.input || $json.text || '').trim();

// Identitate user
const telegramId = isTelegram ? (msg.from?.id || null) : null;
const username   = isTelegram ? (msg.from?.username || '') : 'chat-user';
const firstName  = isTelegram ? (msg.from?.first_name || '') : 'User';
const chatId     = isTelegram ? (msg.chat?.id || null) : ($json.sessionId || 'chat-ui');
const messageId  = isTelegram ? (msg.message_id || null) : null;

if (!text) {
  return [{ json: { error: 'No input text found', raw: $json } }];
}

const urlRegex = /https?:\/\/[^\s]+/i;
const isUrl = urlRegex.test(text);
const inputUrl = isUrl ? text.match(urlRegex)[0] : null;
const inputType = isUrl ? 'url' : 'keyword';
const isRevision = /^(revise|redo|regenerate|modifica|refa|schimba|rescrie|rewrite)/i.test(text);

return [{
  json: {
    chatId,
    telegramId,
    username,
    firstName,
    text,
    inputType,
    inputUrl,
    isRevision,
    messageId
  }
}];

const raw = $json.data || $json.body || '';
const clean = raw
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 4000);

return [{
  json: {
    cleanedContent: clean,
    source: 'url',
    topicId: $('Insert Topic').item.json.id,
    chatId: $('Parse Input').item.json.chatId
  }
}];

return [{
  json: {
    cleanedContent: $('Parse Input').item.json.text,
    source: 'keyword',
    topicId: $('Insert Topic').item.json.id,
    chatId: $('Parse Input').item.json.chatId
  }
}];

const raw = $input.first()?.json?.output
  || $input.first()?.json?.text
  || $json.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw.replace(/```json|```/g, '').trim()); }
catch(e) {
  parsed = { script_hook: raw.substring(0,300), script_body: raw.substring(300,2000),
    script_cta: raw.substring(2000,2300), word_count: raw.split(' ').length, sections: [], voiceover_script: raw };
}
// Support both our format AND faceless format (voiceover_script key)
const hook = parsed.script_hook || parsed.voiceover_script?.substring(0,200) || '';
const body = parsed.script_body || parsed.voiceover_script?.substring(200,1500) || '';
const cta  = parsed.script_cta  || parsed.voiceover_script?.substring(1500,1800) || '';
return [{ json: {
  ...parsed,
  script_hook: hook, script_body: body, script_cta: cta,
  full_script: `${hook}\n\n${body}\n\n${cta}`,
  voiceover_script: parsed.voiceover_script || `${hook}\n\n${body}\n\n${cta}`,
  sections: parsed.sections || [],
  topicId: $('Merge Content').item.json.topicId,
  chatId: $('Merge Content').item.json.chatId
}}];

return [{
  json: {
    ...$('Parse Script Response').item.json,
    draftId: $json.id
  }
}];

const raw = $input.first()?.json?.output
  || $input.first()?.json?.text
  || $json.choices?.[0]?.message?.content || '{}';
let seo;
try { seo = JSON.parse(raw.replace(/```json|```/g, '').trim()); }
catch(e) {
  seo = { title_1:'Title 1', title_2:'Title 2', title_3:'Title 3',
    title_4:'Title 4', title_5:'Title 5', description: raw.substring(0,500),
    tags:[], hashtags:[] };
}
const d = $('Set Draft ID').item.json;
return [{ json: {
  seo,
  draftId: d.draftId, chatId: d.chatId,
  full_script: d.full_script,
  script_hook: d.script_hook, script_body: d.script_body, script_cta: d.script_cta
}}];

// Agent returns text prompt directly (not JSON)
const raw = $input.first()?.json?.output
  || $input.first()?.json?.text
  || $json.choices?.[0]?.message?.content || '';
// Try JSON parse first, fall back to plain text prompt
let thumb;
try { thumb = JSON.parse(raw.replace(/```json|```/g, '').trim()); }
catch(e) { thumb = { prompt_text: raw.trim(), style: 'cinematic', color_palette: [], text_overlay: '' }; }
const d = $('Parse SEO Response').item.json;
return [{ json: {
  thumb,
  draftId: d.draftId,
  chatId: d.chatId,
  seo: d.seo,
  script_hook: d.script_hook,
  script_body: d.script_body,
  script_cta: d.script_cta
}}];

const raw = $input.first()?.json?.output
  || $input.first()?.json?.text
  || $json.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw.replace(/```json|```/g, '').trim()); }
catch(e) { parsed = { script_hook:'', script_body: raw, script_cta:'', word_count: raw.split(' ').length }; }
const latest = $('Get Latest Draft for Revision').item.json;
return [{ json: {
  ...parsed,
  full_script: `${parsed.script_hook||''}\n\n${parsed.script_body||''}\n\n${parsed.script_cta||''}`,
  draftId: latest.draft_id,
  previousScript: latest.full_script || '',
  revisionCount: (latest.revision_count || 0) + 1,
  chatId: $('Parse Input').item.json.chatId,
  instruction: $('Parse Input').item.json.text
}}];

