parameters.jsCode:
const draft = $('Get Latest Draft for Revision').item.json;
const revised = $('Parse Revision Response').item.json;
const input = $('Parse Input').item.json;

const newScript = [
  revised.script_hook || '',
  revised.script_body || '',
  revised.script_cta  || ''
].join('\n\n');

return [{
  json: {
    draft_id:             draft.draft_id,        // ← era draft.id, acum e draft_id
    revision_number:      (draft.revision_count || 0) + 1,
    revision_instruction: input.text,
    previous_script:      draft.full_script || '',
    new_script:           newScript,
    chatId:               input.chatId
  }
}];

const segments = $('Parse Script Response').item.json.srt_segments || [];
const folderId = $('Create Video Folder1').item.json.id;
const slug = $('Parse Script Response').item.json.topic_slug || 'video';

const srtContent = segments.map(s =>
  `${s.index}\n${s.start} --> ${s.end}\n${s.text}\n`
).join('\n');

return [{ json: {
  srtContent,
  folderId,
  slug,
  filename: `${slug}.srt`,
  draftId: $('Set Draft ID').item.json.draftId,
  chatId: $('Parse Input').item.json.chatId,
  runwayPrompts: $('Parse Script Response').item.json.runway_prompts || [],
  voiceoverScript: $('Parse Script Response').item.json.voiceover_script || ''
} }];

const prompts = $('Generate SRT Content1').item.json.runwayPrompts || [];
const folderId = $('Generate SRT Content1').item.json.folderId;
const slug = $('Generate SRT Content1').item.json.slug;
return prompts.map((prompt, i) => ({ json: {
  prompt,
  index: i + 1,
  folderId,
  slug,
  filename: `${slug}-clip-${i+1}.mp4`
} }));

// Poll Runway task until complete
const taskId = $json.id;
const apiKey = 'YOUR_RUNWAY_API_KEY';
let status = 'RUNNING';
let videoUrl = null;
let attempts = 0;

while (status === 'RUNNING' || status === 'THROTTLED') {
  if (attempts++ > 30) break; // max 5 min
  await new Promise(r => setTimeout(r, 10000)); // wait 10s
  const resp = await fetch(`https://api.dev.runwayml.com/v1/tasks/${taskId}`, {
    headers: { 'Authorization': `Bearer ${apiKey}`, 'X-Runway-Version': '2024-11-06' }
  });
  const data = await resp.json();
  status = data.status;
  if (status === 'SUCCEEDED') videoUrl = data.output?.[0];
}

if (!videoUrl) throw new Error('Runway generation failed or timed out');

// Download video
const videoResp = await fetch(videoUrl);
const buffer = await videoResp.arrayBuffer();
const base64 = Buffer.from(buffer).toString('base64');

return [{ json: {
  videoBase64: base64,
  filename: $json.filename,
  folderId: $json.folderId,
  index: $json.index,
  slug: $json.slug
} }];

const items = $input.first().json.data || [];
const slug = items[0]?.slug || 'video';
const folderId = items[0]?.folderId || '';

// Build FFmpeg concat list
const clipPaths = items
  .sort((a,b) => a.index - b.index)
  .map(i => `file 'D:\\n8n-media\\youtube\\${i.filename}'`);

const concatList = clipPaths.join('\n');
const concatFile = `D:\\n8n-media\\youtube\\${slug}-concat.txt`;
const audioFile = `D:\\n8n-media\\youtube\\${slug}-audio.mp3`;
const srtFile   = `D:\\n8n-media\\youtube\\${slug}.srt`;
const outputFile= `D:\\n8n-media\\youtube\\${slug}-SHORT.mp4`;

// FFmpeg command: concat clips + audio + burn subtitles
const ffmpegCmd = [
  `echo '${concatList}' > '${concatFile}'`,
  `ffmpeg -y -f concat -safe 0 -i '${concatFile}' -i '${audioFile}' -vf "subtitles='${srtFile}':force_style='FontSize=18,PrimaryColour=&Hffffff,OutlineColour=&H000000,Bold=1'" -c:v libx264 -c:a aac -shortest '${outputFile}'`
].join(' && ');

return [{ json: {
  ffmpegCmd,
  outputFile,
  slug,
  folderId,
  chatId: $('Parse Input').item.json.chatId
} }];

const { execSync } = require('child_process');
const fs = require('fs');

const cmd = $('Build FFmpeg Command1').item.json.ffmpegCmd;
const outputFile = $('Build FFmpeg Command1').item.json.outputFile;
const slug = $('Build FFmpeg Command1').item.json.slug;
const folderId = $('Build FFmpeg Command1').item.json.folderId;
const chatId = $('Build FFmpeg Command1').item.json.chatId;

// Asigura ca directorul exista
const dir = 'D:\\n8n-media\\youtube';
if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

try {
  const result = execSync(cmd, { timeout: 300000, encoding: 'utf8' });
  return [{ json: {
    success: true,
    outputFile,
    slug,
    folderId,
    chatId,
    ffmpegOutput: result || 'completed'
  } }];
} catch(e) {
  return [{ json: {
    success: false,
    error: e.message,
    outputFile,
    slug,
    folderId,
    chatId
  } }];
}

