const raw = $input.first()?.json?.output || $input.first()?.json?.text || '{}';
let parsed;
try { parsed = JSON.parse(raw.replace(/```json|```/g, '').trim()); }
catch(e) { parsed = { titles: ['Title 1','Title 2','Title 3','Title 4','Title 5'], recommended_index: 0 }; }

const d = $('Set Draft ID').item.json;
return [{ json: {
  titles: parsed.titles || [],
  recommended_index: parsed.recommended_index || 0,
  recommended_title: (parsed.titles || [])[parsed.recommended_index || 0] || 'YouTube Video',
  niche: $('Parse Script Response').item.json.niche || 'general',
  draftId: d.draftId,
  chatId: d.chatId
} }];

// Preia draftId din body sau foloseste ultimul draft
const body = $json.body || $json;
const draftId = body.draftId || null;
const title = body.title || 'Test Upload - YouTube Shorts';
const description = body.description || 'Test upload via n8n webhook';
const tags = body.tags || 'test,youtube,shorts';
return [{ json: { draftId, title, description, tags, isTest: true } }];

const parseInput = $('Parse Input1').item.json;
const upsertUser = $('Upsert Telegram User').item.json;

return [{
  json: {
    telegram_user_id: upsertUser.id,
    keyword: parseInput.inputType !== 'url' ? parseInput.text : null,
    input_url: parseInput.inputUrl || null,
    input_type: parseInput.inputType || 'keyword'
  }
}];

const parseInput = $('Parse Input').item.json;
const upsertUser = $('Upsert Telegram User').item.json;

const telegramUserId = upsertUser.id;
const inputType = parseInput.inputType || 'keyword';
const text = parseInput.text || '';
const inputUrl = parseInput.inputUrl || null;
const keyword = inputType !== 'url' ? text : null;

const keywordSql = keyword ? `'${keyword.replace(/'/g, "''")}'` : 'NULL';
const inputUrlSql = inputUrl ? `'${inputUrl.replace(/'/g, "''")}'` : 'NULL';

const query = `INSERT INTO youtube_topics (telegram_user_id, keyword, input_url, input_type) VALUES ('${telegramUserId}', ${keywordSql}, ${inputUrlSql}, '${inputType}') RETURNING id;`;

return [{ json: { query, telegram_user_id: telegramUserId, keyword, input_url: inputUrl, input_type: inputType } }];
